-- Kadreo ERP core schema (spec section 4).
-- Every business table carries tenant_id from day one (D-02) and is protected by PostgreSQL
-- Row-Level Security: the application connects as kadreo_app (not the owner) and sets
-- app.tenant_id on each connection from the authenticated token. Money is numeric(18,2) with
-- a currency code; time is timestamptz in UTC; ids are UUID v7 generated by the application.

CREATE EXTENSION IF NOT EXISTS postgis;

DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'kadreo_app') THEN
        -- Login and password are set per environment, never in migrations.
        CREATE ROLE kadreo_app NOLOGIN;
    END IF;
END
$$;

CREATE OR REPLACE FUNCTION current_tenant_id() RETURNS uuid
    LANGUAGE sql STABLE AS
$$ SELECT nullif(current_setting('app.tenant_id', true), '')::uuid $$;

-- Common columns, repeated per table for clarity:
--   id uuid PK, tenant_id uuid, created_at, created_by, updated_at, updated_by, version

/* ------------------------------------------------------------------------- tenant */

CREATE TABLE tenant (
    id             uuid PRIMARY KEY,
    name           text        NOT NULL,
    default_locale text        NOT NULL DEFAULT 'pl',
    branding       jsonb       NOT NULL,
    settings       jsonb       NOT NULL DEFAULT '{}',
    created_at     timestamptz NOT NULL DEFAULT now(),
    updated_at     timestamptz NOT NULL DEFAULT now(),
    version        integer     NOT NULL DEFAULT 0
);

CREATE TABLE legal_entity (
    id         uuid PRIMARY KEY,
    tenant_id  uuid        NOT NULL REFERENCES tenant (id),
    name       text        NOT NULL,
    nip        text        NOT NULL,
    country    char(2)     NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by uuid,
    updated_at timestamptz NOT NULL DEFAULT now(),
    updated_by uuid,
    version    integer     NOT NULL DEFAULT 0,
    deleted_at timestamptz
);

/* -------------------------------------------------------------- users and access */

CREATE TABLE app_user (
    id         uuid PRIMARY KEY,
    tenant_id  uuid        NOT NULL REFERENCES tenant (id),
    email      text        NOT NULL,
    full_name  text        NOT NULL,
    locale     text        NOT NULL DEFAULT 'pl',
    status     text        NOT NULL DEFAULT 'active',
    access_until date,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by uuid,
    updated_at timestamptz NOT NULL DEFAULT now(),
    updated_by uuid,
    version    integer     NOT NULL DEFAULT 0,
    UNIQUE (tenant_id, email)
);

-- System role templates have tenant_id NULL; tenants add their own roles (3.3).
CREATE TABLE role (
    id        uuid PRIMARY KEY,
    tenant_id uuid REFERENCES tenant (id),
    code      text NOT NULL,
    name      text NOT NULL,
    UNIQUE (tenant_id, code)
);

CREATE TABLE role_permission (
    role_id    uuid NOT NULL REFERENCES role (id) ON DELETE CASCADE,
    permission text NOT NULL,
    PRIMARY KEY (role_id, permission)
);

CREATE TABLE user_role (
    tenant_id uuid NOT NULL REFERENCES tenant (id),
    user_id   uuid NOT NULL REFERENCES app_user (id) ON DELETE CASCADE,
    role_id   uuid NOT NULL REFERENCES role (id),
    PRIMARY KEY (user_id, role_id)
);

-- Data scope (3.1): regions for OPS_MANAGER, sites for SITE_MANAGER. No rows = whole tenant.
CREATE TABLE user_scope (
    tenant_id uuid NOT NULL REFERENCES tenant (id),
    user_id   uuid NOT NULL REFERENCES app_user (id) ON DELETE CASCADE,
    kind      text NOT NULL CHECK (kind IN ('region', 'site')),
    value     text NOT NULL,
    PRIMARY KEY (user_id, kind, value)
);

-- Append-only audit log (7.3 p. 5): the application role may insert and read, never change.
CREATE TABLE audit_log (
    id          uuid PRIMARY KEY,
    tenant_id   uuid        NOT NULL REFERENCES tenant (id),
    at          timestamptz NOT NULL DEFAULT now(),
    actor_id    uuid,
    entity      text        NOT NULL,
    entity_id   text        NOT NULL,
    action      text        NOT NULL,
    before      jsonb,
    after       jsonb,
    ip          text,
    device      text
);
CREATE INDEX audit_log_entity_idx ON audit_log (tenant_id, entity, entity_id, at DESC);

/* --------------------------------------------------------------------- dictionaries */

CREATE TABLE competence (
    id                     uuid PRIMARY KEY,
    tenant_id              uuid    NOT NULL REFERENCES tenant (id),
    code                   text    NOT NULL,
    name                   jsonb   NOT NULL,
    kind                   text    NOT NULL DEFAULT 'skill' CHECK (kind IN ('skill', 'language')),
    required_document_type text,
    UNIQUE (tenant_id, code)
);

CREATE TABLE position (
    id        uuid PRIMARY KEY,
    tenant_id uuid  NOT NULL REFERENCES tenant (id),
    code      text  NOT NULL,
    name      jsonb NOT NULL,
    UNIQUE (tenant_id, code)
);

CREATE TABLE position_competence (
    tenant_id     uuid NOT NULL REFERENCES tenant (id),
    position_id   uuid NOT NULL REFERENCES position (id) ON DELETE CASCADE,
    competence_id uuid NOT NULL REFERENCES competence (id),
    PRIMARY KEY (position_id, competence_id)
);

CREATE TABLE reason (
    id        uuid PRIMARY KEY,
    tenant_id uuid  NOT NULL REFERENCES tenant (id),
    kind      text  NOT NULL CHECK (kind IN ('correction', 'dispute')),
    code      text  NOT NULL,
    name      jsonb NOT NULL,
    sort      integer NOT NULL DEFAULT 0,
    UNIQUE (tenant_id, kind, code)
);

/* ---------------------------------------------------------- clients, sites, contracts */

CREATE TABLE client (
    id              uuid PRIMARY KEY,
    tenant_id       uuid        NOT NULL REFERENCES tenant (id),
    name            text        NOT NULL,
    short_name      text        NOT NULL,
    nip             text        NOT NULL,
    country         char(2)     NOT NULL,
    manager_user_id uuid REFERENCES app_user (id),
    created_at      timestamptz NOT NULL DEFAULT now(),
    created_by      uuid,
    updated_at      timestamptz NOT NULL DEFAULT now(),
    updated_by      uuid,
    version         integer     NOT NULL DEFAULT 0,
    deleted_at      timestamptz
);

CREATE TABLE site (
    id                  uuid PRIMARY KEY,
    tenant_id           uuid        NOT NULL REFERENCES tenant (id),
    client_id           uuid        NOT NULL REFERENCES client (id),
    name                text        NOT NULL,
    city                text        NOT NULL,
    address             text        NOT NULL,
    country             char(2)     NOT NULL,
    region              text        NOT NULL,
    time_zone           text        NOT NULL,
    location            geography(Point, 4326) NOT NULL,
    geofence            geometry(Polygon, 4326),
    manager_name        text        NOT NULL,
    clock_methods       text[]      NOT NULL,
    access_control      jsonb       NOT NULL DEFAULT '{"kind":"none"}',
    late_threshold_min  integer     NOT NULL DEFAULT 5,
    clock_window_min    integer     NOT NULL DEFAULT 30,
    outside_geofence    text        NOT NULL DEFAULT 'allow_flagged' CHECK (outside_geofence IN ('allow_flagged', 'deny')),
    team_leader_name    text,
    created_at          timestamptz NOT NULL DEFAULT now(),
    created_by          uuid,
    updated_at          timestamptz NOT NULL DEFAULT now(),
    updated_by          uuid,
    version             integer     NOT NULL DEFAULT 0,
    deleted_at          timestamptz
);
CREATE INDEX site_client_idx ON site (tenant_id, client_id);

CREATE TABLE contract (
    id                  uuid PRIMARY KEY,
    tenant_id           uuid        NOT NULL REFERENCES tenant (id),
    number              text        NOT NULL,
    client_id           uuid        NOT NULL REFERENCES client (id),
    legal_entity_id     uuid        NOT NULL REFERENCES legal_entity (id),
    currency            char(3)     NOT NULL,
    status              text        NOT NULL,
    version_no          integer     NOT NULL DEFAULT 1,
    version_from        date        NOT NULL,
    valid_from          date        NOT NULL,
    valid_to            date        NOT NULL,
    timesheet_period    text        NOT NULL CHECK (timesheet_period IN ('week', 'two_weeks', 'month')),
    auto_accept_hours   integer     NOT NULL DEFAULT 72,
    payment_days        integer     NOT NULL DEFAULT 30,
    show_rates_in_portal boolean    NOT NULL DEFAULT false,
    sla                 jsonb       NOT NULL,
    kpi_targets         jsonb       NOT NULL,
    created_at          timestamptz NOT NULL DEFAULT now(),
    created_by          uuid,
    updated_at          timestamptz NOT NULL DEFAULT now(),
    updated_by          uuid,
    version             integer     NOT NULL DEFAULT 0,
    UNIQUE (tenant_id, number)
);

CREATE TABLE rate_card (
    id           uuid PRIMARY KEY,
    tenant_id    uuid          NOT NULL REFERENCES tenant (id),
    contract_id  uuid          NOT NULL REFERENCES contract (id) ON DELETE CASCADE,
    position_id  uuid          NOT NULL REFERENCES position (id),
    rate_type    text          NOT NULL DEFAULT 'hourly' CHECK (rate_type IN ('hourly', 'piece', 'fixed_shift')),
    amount       numeric(18, 2) NOT NULL,
    previous     numeric(18, 2),
    valid_from   date          NOT NULL,
    valid_to     date
);

CREATE TABLE project (
    id           uuid PRIMARY KEY,
    tenant_id    uuid        NOT NULL REFERENCES tenant (id),
    site_id      uuid        NOT NULL REFERENCES site (id),
    contract_id  uuid        NOT NULL REFERENCES contract (id),
    name         text        NOT NULL,
    manager_name text        NOT NULL,
    status       text        NOT NULL DEFAULT 'active',
    created_at   timestamptz NOT NULL DEFAULT now(),
    created_by   uuid,
    updated_at   timestamptz NOT NULL DEFAULT now(),
    updated_by   uuid,
    version      integer     NOT NULL DEFAULT 0
);

CREATE TABLE shift_template (
    id               uuid PRIMARY KEY,
    tenant_id        uuid    NOT NULL REFERENCES tenant (id),
    project_id       uuid    NOT NULL REFERENCES project (id) ON DELETE CASCADE,
    position_id      uuid    NOT NULL REFERENCES position (id),
    start_time       time    NOT NULL,
    end_time         time    NOT NULL,
    unpaid_break_min integer NOT NULL DEFAULT 0,
    sort_order       integer NOT NULL DEFAULT 0
);

-- Planned headcount per template and date; no row = no shift that day.
CREATE TABLE shift_plan (
    tenant_id   uuid    NOT NULL REFERENCES tenant (id),
    template_id uuid    NOT NULL REFERENCES shift_template (id) ON DELETE CASCADE,
    date        date    NOT NULL,
    planned     integer NOT NULL CHECK (planned >= 0),
    cancelled   boolean NOT NULL DEFAULT false,
    PRIMARY KEY (template_id, date)
);

CREATE TABLE schedule_week (
    tenant_id  uuid NOT NULL REFERENCES tenant (id),
    project_id uuid NOT NULL REFERENCES project (id) ON DELETE CASCADE,
    monday     date NOT NULL,
    state      text NOT NULL CHECK (state IN ('draft', 'published', 'changed_after_publish')),
    published_at timestamptz,
    published_by uuid,
    PRIMARY KEY (project_id, monday)
);

/* -------------------------------------------------------------------------- workers */

CREATE TABLE worker (
    id                uuid PRIMARY KEY,
    tenant_id         uuid             NOT NULL REFERENCES tenant (id),
    number            text             NOT NULL,
    first_name        text             NOT NULL,
    last_name         text             NOT NULL,
    phone             text             NOT NULL,
    citizenship       char(2)          NOT NULL,
    language          text             NOT NULL,
    contract_kind     text             NOT NULL CHECK (contract_kind IN ('uop', 'zlecenie', 'b2b')),
    home              geography(Point, 4326),
    prefers_morning   boolean          NOT NULL DEFAULT false,
    weekly_hour_limit integer          NOT NULL DEFAULT 48,
    status            text             NOT NULL,
    status_until      date,
    badge_count       integer          NOT NULL DEFAULT 0,
    rating            numeric(3, 1)    NOT NULL DEFAULT 4.0,
    created_at        timestamptz      NOT NULL DEFAULT now(),
    created_by        uuid,
    updated_at        timestamptz      NOT NULL DEFAULT now(),
    updated_by        uuid,
    version           integer          NOT NULL DEFAULT 0,
    deleted_at        timestamptz,
    UNIQUE (tenant_id, number)
);
CREATE INDEX worker_name_idx ON worker (tenant_id, lower(last_name), lower(first_name));

CREATE TABLE worker_position (
    tenant_id   uuid NOT NULL REFERENCES tenant (id),
    worker_id   uuid NOT NULL REFERENCES worker (id) ON DELETE CASCADE,
    position_id uuid NOT NULL REFERENCES position (id),
    PRIMARY KEY (worker_id, position_id)
);

CREATE TABLE worker_competence (
    tenant_id     uuid NOT NULL REFERENCES tenant (id),
    worker_id     uuid NOT NULL REFERENCES worker (id) ON DELETE CASCADE,
    competence_id uuid NOT NULL REFERENCES competence (id),
    PRIMARY KEY (worker_id, competence_id)
);

-- Shifts worked per site: feeds the candidate score ("опыт на объекте").
CREATE TABLE worker_site_experience (
    tenant_id uuid    NOT NULL REFERENCES tenant (id),
    worker_id uuid    NOT NULL REFERENCES worker (id) ON DELETE CASCADE,
    site_id   uuid    NOT NULL REFERENCES site (id),
    shifts    integer NOT NULL DEFAULT 0,
    PRIMARY KEY (worker_id, site_id)
);

CREATE TABLE worker_document (
    id         uuid PRIMARY KEY,
    tenant_id  uuid        NOT NULL REFERENCES tenant (id),
    worker_id  uuid        NOT NULL REFERENCES worker (id) ON DELETE CASCADE,
    type       text        NOT NULL,
    number     text,
    valid_to   date,
    status     text        NOT NULL DEFAULT 'accepted',
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    version    integer     NOT NULL DEFAULT 0
);
CREATE INDEX worker_document_worker_idx ON worker_document (tenant_id, worker_id);
CREATE INDEX worker_document_valid_to_idx ON worker_document (tenant_id, valid_to);

/* ---------------------------------------------------------------------- assignments */

CREATE TABLE assignment (
    id          uuid PRIMARY KEY,
    tenant_id   uuid        NOT NULL REFERENCES tenant (id),
    worker_id   uuid        NOT NULL REFERENCES worker (id),
    template_id uuid        NOT NULL REFERENCES shift_template (id),
    date        date        NOT NULL,
    status      text        NOT NULL CHECK (status IN ('proposed', 'confirmed', 'declined', 'cancelled')),
    source      text        NOT NULL CHECK (source IN ('manual', 'ai')),
    replaces_id uuid REFERENCES assignment (id),
    created_at  timestamptz NOT NULL DEFAULT now(),
    created_by  uuid,
    updated_at  timestamptz NOT NULL DEFAULT now(),
    updated_by  uuid,
    version     integer     NOT NULL DEFAULT 0
);
CREATE INDEX assignment_cell_idx ON assignment (tenant_id, template_id, date);
CREATE INDEX assignment_worker_idx ON assignment (tenant_id, worker_id, date);
-- One active assignment per worker per template and date.
CREATE UNIQUE INDEX assignment_active_uq ON assignment (worker_id, template_id, date) WHERE status IN ('proposed', 'confirmed');

CREATE TABLE auto_assign_job (
    id          uuid PRIMARY KEY,
    tenant_id   uuid        NOT NULL REFERENCES tenant (id),
    project_id  uuid        NOT NULL REFERENCES project (id),
    status      text        NOT NULL,
    request     jsonb       NOT NULL,
    result      jsonb,
    started_at  timestamptz NOT NULL DEFAULT now(),
    finished_at timestamptz
);

/* ------------------------------------------------------------------ time tracking */

CREATE TABLE clock_event (
    id              uuid PRIMARY KEY,
    tenant_id       uuid        NOT NULL REFERENCES tenant (id),
    worker_id       uuid        NOT NULL REFERENCES worker (id),
    assignment_id   uuid REFERENCES assignment (id),
    site_id         uuid        NOT NULL REFERENCES site (id),
    type            text        NOT NULL CHECK (type IN ('in', 'break_start', 'break_end', 'out')),
    device_time     timestamptz NOT NULL,
    server_time     timestamptz NOT NULL,
    source          text        NOT NULL,
    gps_accuracy_m  integer,
    photo           boolean     NOT NULL DEFAULT false,
    face_match      boolean,
    gate            integer,
    kiosk           integer,
    qr_point        integer,
    offline         boolean     NOT NULL DEFAULT false,
    idempotency_key text,
    UNIQUE (tenant_id, idempotency_key)
);
CREATE INDEX clock_event_worker_idx ON clock_event (tenant_id, worker_id, server_time);
CREATE INDEX clock_event_site_idx ON clock_event (tenant_id, site_id, server_time);

CREATE TABLE timesheet (
    id                         uuid PRIMARY KEY,
    tenant_id                  uuid        NOT NULL REFERENCES tenant (id),
    project_id                 uuid        NOT NULL REFERENCES project (id),
    period_from                date        NOT NULL,
    period_to                  date        NOT NULL,
    team_leader_days_confirmed integer     NOT NULL DEFAULT 0,
    manager_confirmed          boolean     NOT NULL DEFAULT false,
    client_stage               text        NOT NULL DEFAULT 'not_sent'
        CHECK (client_stage IN ('not_sent', 'waiting', 'confirmed', 'disputed', 'auto_accepted')),
    client_due_at              timestamptz,
    sent_at                    timestamptz,
    sent_by                    uuid,
    version                    integer     NOT NULL DEFAULT 0,
    UNIQUE (project_id, period_from)
);

CREATE TABLE timesheet_entry (
    id             uuid PRIMARY KEY,
    tenant_id      uuid          NOT NULL REFERENCES tenant (id),
    timesheet_id   uuid          NOT NULL REFERENCES timesheet (id) ON DELETE CASCADE,
    worker_id      uuid          NOT NULL REFERENCES worker (id),
    position_id    uuid          NOT NULL REFERENCES position (id),
    assignment_id  uuid REFERENCES assignment (id),
    date           date          NOT NULL,
    shift_label    text,
    planned_hours  numeric(5, 2) NOT NULL,
    payable_hours  numeric(5, 2) NOT NULL,
    billable_hours numeric(5, 2) NOT NULL,
    issue_kind     text,
    issue_minutes  integer,
    disputed       boolean       NOT NULL DEFAULT false,
    version        integer       NOT NULL DEFAULT 0,
    UNIQUE (timesheet_id, worker_id, date)
);
CREATE INDEX timesheet_entry_ts_idx ON timesheet_entry (tenant_id, timesheet_id);

CREATE TABLE timesheet_correction (
    id               uuid PRIMARY KEY,
    tenant_id        uuid          NOT NULL REFERENCES tenant (id),
    entry_id         uuid          NOT NULL REFERENCES timesheet_entry (id) ON DELETE CASCADE,
    at               timestamptz   NOT NULL,
    by_user_id       uuid,
    by_name          text          NOT NULL,
    payable_before   numeric(5, 2) NOT NULL,
    payable_after    numeric(5, 2) NOT NULL,
    billable_before  numeric(5, 2) NOT NULL,
    billable_after   numeric(5, 2) NOT NULL,
    reason_id        uuid          NOT NULL REFERENCES reason (id),
    comment          text          NOT NULL DEFAULT ''
);

/* --------------------------------------------------------------------- operations */

CREATE TABLE alert (
    id                 uuid PRIMARY KEY,
    tenant_id          uuid        NOT NULL REFERENCES tenant (id),
    kind               text        NOT NULL,
    severity           text        NOT NULL CHECK (severity IN ('critical', 'warning', 'info')),
    site_id            uuid        NOT NULL REFERENCES site (id),
    title              jsonb       NOT NULL,
    context            jsonb       NOT NULL,
    created_at         timestamptz NOT NULL,
    escalation_level   integer     NOT NULL DEFAULT 1,
    next_escalation_at timestamptz,
    sla_due_at         timestamptz,
    status             text        NOT NULL CHECK (status IN ('open', 'taken', 'closed')),
    taken_by           uuid,
    taken_by_name      text,
    taken_at           timestamptz,
    count              integer     NOT NULL DEFAULT 1,
    shift_ref          jsonb,
    version            integer     NOT NULL DEFAULT 0
);
CREATE INDEX alert_open_idx ON alert (tenant_id, status, severity);

CREATE TABLE staff_request (
    id          uuid PRIMARY KEY,
    tenant_id   uuid        NOT NULL REFERENCES tenant (id),
    number      integer     NOT NULL,
    site_id     uuid        NOT NULL REFERENCES site (id),
    position_id uuid        NOT NULL REFERENCES position (id),
    headcount   integer     NOT NULL,
    assigned    integer     NOT NULL DEFAULT 0,
    date_from   date        NOT NULL,
    date_to     date        NOT NULL,
    status      text        NOT NULL,
    sla_due_at  timestamptz NOT NULL,
    created_at  timestamptz NOT NULL DEFAULT now(),
    version     integer     NOT NULL DEFAULT 0,
    UNIQUE (tenant_id, number)
);

CREATE TABLE urgent_request (
    id          uuid PRIMARY KEY,
    tenant_id   uuid        NOT NULL REFERENCES tenant (id),
    site_id     uuid        NOT NULL REFERENCES site (id),
    template_id uuid        NOT NULL REFERENCES shift_template (id),
    date        date        NOT NULL,
    headcount   integer     NOT NULL,
    comment     text        NOT NULL DEFAULT '',
    offered_to  integer     NOT NULL DEFAULT 0,
    accepted    integer     NOT NULL DEFAULT 0,
    created_at  timestamptz NOT NULL DEFAULT now(),
    created_by  uuid
);

CREATE TABLE notification (
    id        uuid PRIMARY KEY,
    tenant_id uuid        NOT NULL REFERENCES tenant (id),
    user_id   uuid        NOT NULL REFERENCES app_user (id) ON DELETE CASCADE,
    kind      text        NOT NULL,
    title     jsonb       NOT NULL,
    href      text,
    at        timestamptz NOT NULL,
    read      boolean     NOT NULL DEFAULT false
);
CREATE INDEX notification_user_idx ON notification (tenant_id, user_id, at DESC);

/* -------------------------------------------------------------- row-level security */

DO $$
DECLARE
    t text;
BEGIN
    FOREACH t IN ARRAY ARRAY[
        'legal_entity', 'app_user', 'user_role', 'user_scope', 'audit_log', 'competence', 'position',
        'position_competence', 'reason', 'client', 'site', 'contract', 'rate_card', 'project',
        'shift_template', 'shift_plan', 'schedule_week', 'worker', 'worker_position', 'worker_competence',
        'worker_site_experience', 'worker_document', 'assignment', 'auto_assign_job', 'clock_event',
        'timesheet', 'timesheet_entry', 'timesheet_correction', 'alert', 'staff_request', 'urgent_request',
        'notification']
    LOOP
        EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t);
        EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', t);
        EXECUTE format('CREATE POLICY tenant_isolation ON %I USING (tenant_id = current_tenant_id()) WITH CHECK (tenant_id = current_tenant_id())', t);
        EXECUTE format('GRANT SELECT, INSERT, UPDATE, DELETE ON %I TO kadreo_app', t);
    END LOOP;
END
$$;

-- The tenant row itself is visible only to its own sessions.
ALTER TABLE tenant ENABLE ROW LEVEL SECURITY;
ALTER TABLE tenant FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_self ON tenant USING (id = current_tenant_id());
GRANT SELECT, UPDATE ON tenant TO kadreo_app;

-- System role templates (tenant_id NULL) are readable by every tenant.
ALTER TABLE role ENABLE ROW LEVEL SECURITY;
ALTER TABLE role FORCE ROW LEVEL SECURITY;
CREATE POLICY role_visible ON role USING (tenant_id IS NULL OR tenant_id = current_tenant_id())
    WITH CHECK (tenant_id = current_tenant_id());
GRANT SELECT, INSERT, UPDATE, DELETE ON role TO kadreo_app;
ALTER TABLE role_permission ENABLE ROW LEVEL SECURITY;
ALTER TABLE role_permission FORCE ROW LEVEL SECURITY;
CREATE POLICY role_permission_visible ON role_permission
    USING (EXISTS (SELECT 1 FROM role r WHERE r.id = role_id));
GRANT SELECT, INSERT, DELETE ON role_permission TO kadreo_app;

-- Audit log is append-only for the application.
REVOKE UPDATE, DELETE ON audit_log FROM kadreo_app;

GRANT EXECUTE ON FUNCTION current_tenant_id() TO kadreo_app;
GRANT USAGE ON SCHEMA public TO kadreo_app;
